changeSet.sql:
ALTER TABLE health_info
    ADD CONSTRAINT chk_health_info_blood_type
        CHECK (blood_type IN ('A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'));

ALTER TABLE health_info
    ADD CONSTRAINT chk_health_info_smoking_frequency
        CHECK (
            (is_smoking = FALSE AND smoking_frequency IS NULL) OR
            (is_smoking = TRUE AND smoking_frequency IN ('LIGHT', 'MODERATE', 'HEAVY'))
            );

ALTER TABLE health_info
    ADD CONSTRAINT chk_health_info_alcohol_consumption
        CHECK (alcohol_consumption IN ('NONE', 'OCCASIONAL', 'REGULAR', 'HEAVY'));

ALTER TABLE health_info
    ADD CONSTRAINT chk_health_info_chronic_disease
        CHECK (
            (has_chronic_disease = FALSE AND chronic_disease_details IS NULL) OR
            (has_chronic_disease = TRUE AND chronic_disease_details IS NOT NULL)
            );

ALTER TABLE health_info
    ADD CONSTRAINT chk_health_info_surgeries
        CHECK (
            (has_past_surgeries = FALSE AND surgery_details IS NULL) OR
            (has_past_surgeries = TRUE AND surgery_details IS NOT NULL)
            );

